var my_jquery_selectors = [];
// ... append to my_jquery_selectors from various parts of the codebase ...
$(my_jquery_selectors.join(&quot;,&quot;)).html(&quot;the code is more readable with the comma left in place&quot;);","timestamp":1316010620,"attachments":[]},{"id":1,"commenterId":1948758734812428220,"content":"Simple enough. I was working on some join() and split() optimization for jquery but got side tracked. I'll keep that in mind.","timestamp":1316040662,"attachments":[]},{"id":2,"commenterId":6454800031398885070,"content":"We can handle the literal case '[a,b].join(",")' but the general case 'a.join(",")' requires type information.  We don't currently use type inference to do this kind of optimization.","timestamp":1317052048,"attachments":[]},{"id":3,"commenterId":1328304962299559429,"content":"This issue was closed by revision r1536.","timestamp":1320089308,"attachments":[]}]}
